package com.bitwarden.sdk;

import com.bitwarden.sdk.schema.*;

import java.util.function.Function;

public class AuthClient {

    private final CommandRunner commandRunner;

    AuthClient(CommandRunner commandRunner) {
        this.commandRunner = commandRunner;
    }

    public AccessTokenLoginResponse loginAccessToken(String accessToken, String stateFile) {
        Command command = new Command();
        AccessTokenLoginRequest accessTokenLoginRequest = new AccessTokenLoginRequest();
        accessTokenLoginRequest.setAccessToken(accessToken);
        accessTokenLoginRequest.setStateFile(stateFile);

        command.setLoginAccessToken(accessTokenLoginRequest);

        ResponseForAccessTokenLoginResponse response = commandRunner.runCommand(command,
            BitwardenClient.throwingFunctionWrapper(Converter::ResponseForAccessTokenLoginResponseFromJsonString));

        if (response == null || !response.getSuccess()) {
            throw new BitwardenClientException(response != null ? response.getErrorMessage() : "Login failed");
        }

        return response.getData();
    }
}

## Bitwarden Secrets Manager SDK

Node-API bindings for interacting with the Bitwarden Secrets Manager. This is a beta release and
might be missing some functionality.

## Getting started

```ts
import { BitwardenClient, ClientSettings, DeviceType, LogLevel } from "@bitwarden/sdk-napi";

// Optional settings
const settings: ClientSettings = {
  apiUrl: "https://api.bitwarden.com",
  identityUrl: "https://identity.bitwarden.com",
  userAgent: "Bitwarden SDK",
  deviceType: DeviceType.SDK,
};

const accessToken = "-- REDACTED --";
const stateFile = "some/path/to/state/file";

const client = new BitwardenClient(settings, LogLevel.Info);

// Authenticating using a machine account access token
await client.auth().loginAccessToken(accessToken, stateFile);

// List secrets
const secrets = await client.secrets().list();

// Get a specific secret
const secret = await client.secrets().get("secret-id");
```

﻿namespace Bitwarden.Sdk;

public class BitwardenAuthException : Exception
{
    public BitwardenAuthException(string message) : base(message)
    {
    }

    public BitwardenAuthException(string message, Exception innerException)
        : base(message, innerException)
    {
    }
}

﻿namespace Bitwarden.Sdk;

public class AuthClient
{
    private readonly CommandRunner _commandRunner;

    internal AuthClient(CommandRunner commandRunner)
    {
        _commandRunner = commandRunner;
    }

    public async Task LoginAccessTokenAsync(string accessToken, string stateFile = "", CancellationToken cancellationToken = default)
    {
        var command = new Command { LoginAccessToken = new AccessTokenLoginRequest { AccessToken = accessToken, StateFile = stateFile } };
        var response = await _commandRunner.RunCommandAsync<ResponseForAccessTokenLoginResponse>(command, cancellationToken);
        if (response is not { Success: true })
        {
            throw new BitwardenAuthException(response != null ? response.ErrorMessage : "Login failed");
        }
    }
}
